/**
 * recupero le stazioni e le visualizzo
 */
async function addStazioni() {

    document.getElementById('tabellaStazioni').innerHTML = 'Recupero stazioni';

    const lnk = lnkStazioni + '?rnd=' + Math.random();  
    const response = await fetch(lnk);
    const jsonResponse = (await response.json());
    const stzData = jsonResponse.data;

    TabellaStazioni(stzData);

    // metto il simbolo di ordine iniziale
    SortColumn = 0;
    SortType = 'ASC';
    MettiSimboloOrdinamento();

}

/**
 * 
 */
function addHeadColumn(rowTab, nome, ordine) {

    const cell = rowTab.insertCell(-1);
    cell.style.textAlign = "center";
    cell.style.verticalAlign = 'middle';

    cell.style.position = "sticky";
    cell.style.top = 0;

    cell.style.backgroundColor = btnBackgroundColor;

    if ( nome.length > 0 ) {
        cell.innerHTML = nome + '<span id="colonna_' + ordine + '"></span>';
        cell.addEventListener('click', evt => ordinaTabella(ordine) );
        cell.onmouseover = function () { cell.style.cursor = "pointer"; }
        cell.onmouseout = function () { cell.style.cursor = "default"; }
    }

}

/**
 * 
 */
function addCellValue(row, Valore, allineamento = 'right') {
    const col = row.insertCell(-1);
    col.innerHTML = Valore;
    col.style.textAlign = allineamento;
    col.style.verticalAlign = 'middle';
    if (allineamento == 'right') {
        col.style.paddingRight = '10px';
    }
}


function isNumeric(n) {
    return !isNaN(parseFloat(n)) && isFinite(n);
  }

/**
 * 
 * @param {*} x 
 */
function SanitizeSort(x) {

    // gestione delle celle vuote

    let y = x;
    if (x === undefined || x === null || x === '' ) {
        if (SortType == 'ASC') {
            y = 99999;
        } else {
            y = -99999;
        }
    } else {
        if ( isNumeric(x) ) {
            y = Number( x );
        }
    }

    return y;

}

/**
 * 
 */
function compareValues(a, b) {

    // questo per fare l'ordinamento su colonna numerica e nome stazione
    // objs.sort((a,b)=> (a.age - b.age || a.name.localeCompare(b.name)  ));

    const aa = SanitizeSort(a.cells[ SortColumn ].textContent);
    const bb = SanitizeSort(b.cells[ SortColumn ].textContent);

    let ordine;
    if (SortType == 'ASC') {
        ordine = (aa < bb) ? -1 : (aa > bb) ? 1 : 0;
    } else {
        ordine = (aa > bb) ? -1 : (aa < bb) ? 1 : 0;
    }
    ordine = ordine || a.cells[ 0 ].textContent.localeCompare(b.cells[ 0 ].textContent);
    return ordine;
}


/**
 * metto il simbolo dell'ordinamento
 */
function MettiSimboloOrdinamento() {

    let symb = document.getElementById( 'colonna_' + SortColumn );
    if (SortType == 'ASC') {
        symb.innerHTML = ' ▲';    
    } else {
        symb.innerHTML = ' ▼';    
    }

}


/**
 * https://stackoverflow.com/questions/55462632/javascript-sort-table-column-on-click
 * risposta con 8
 */
function ordinaTabella(colnum) {

    document.body.style.cursor = 'wait';

    // tolgo il simbolo di ordine
    let symb = document.getElementById( 'colonna_' + SortColumn );
    symb.innerHTML = '';

    // direzione dell'ordinamento
    if (SortColumn == colnum) {
        if (SortType == 'ASC') {
            SortType = 'DESC';
        } else {
            SortType = 'ASC';
        }
    } else {
        SortType = 'ASC';
    }
    SortColumn = colnum ;

    // metto il simbolo di ordine
    MettiSimboloOrdinamento();

    let table = document.getElementById("eleStazioni");

    // get all the rows in this table:
    let righeTabella = Array.from(table.querySelectorAll('tr'));

    // but ignore the heading row:
    righeTabella = righeTabella.slice(1);

    // and then just... sort the rows:
    righeTabella.sort( function(r1, r2) {

        // aggiungo sempre il nome della stazione per ordinare su numeri uguali

        const t1 = r1.cells[ SortColumn ];
        const t2 = r2.cells[ SortColumn ];

        return compareValues(r1, r2);

    });

    // and then the magic part that makes the sorting appear on-page:
    righeTabella.forEach(row => table.appendChild(row));

    document.body.style.cursor = 'auto';    

}

/**
 * 
 */
function UnDecimale(x) {

    if ( isNumeric(x) ) {
        x = parseFloat( x ).toFixed(1);
    }

    return x;
}

/**
 * Visualizzo la tabella delle stazioni meteo
 */
function TabellaStazioni(stzData) {

    document.getElementById('tabellaStazioni').innerHTML = 'Caricamento dati';

    var table = document.createElement('table');
    table.setAttribute('id', 'eleStazioni');
    table.setAttribute('class', 'table table-sm table-striped table-bordered table-hover table-condensed');
    var body = table.createTBody();

    var rowTab = body.insertRow(-1);
    addHeadColumn(rowTab, 'Nome stazione', 0);
    addHeadColumn(rowTab, 'Altitudine<br>(m s.l.m.)', 1 );
    addHeadColumn(rowTab, 'Provincia', 2 );
    addHeadColumn(rowTab, 'Orario<sup>(1)</sup><br>(solare)', 3 );
    addHeadColumn(rowTab, 'Ultima<br>temperatura<sup>(2)</sup><br>(°C)', 4 );
    addHeadColumn(rowTab, 'Temperatura<br>minima<sup>(3)</sup><br>(°C)', 5 );
    addHeadColumn(rowTab, 'Temperatura<br>massima<sup>(4)</sup><br>(°C)', 6 );
    if (COLONNA == 'humidex') {
        addHeadColumn(rowTab, 'Humidex<sup>(5)</sup>', 7 );
    }
    if (COLONNA == 'windchill') {
        addHeadColumn(rowTab, 'Windchill<sup>(5)</sup>', 7 );
    }
    addHeadColumn(rowTab, 'Precipitazione<sup>(6)</sup><br>cumulata (mm)', 8 );
    addHeadColumn(rowTab, 'Raffica vento<sup>(7)</sup><br>(km/h)', 9 );
    if (METTI_NEVE) {
        addHeadColumn(rowTab, 'Altezza neve<sup>(8)</sup><br>(cm)', 10);
    }        
    addHeadColumn(rowTab, '' );

    let sPostille = 
        "<br><sup>(1)</sup> Orario dell'ultimo valore registrato dalla stazione" + 
        "<br><sup>(2)</sup> Temperatura aria all'orario di aggiornamento" + 
        "<br><sup>(3)</sup> Temperatura aria minima di oggi fino all'orario di aggiornamento (la temperatura minima della giornata normalmente si verifica verso l'alba)" +
        "<br><sup>(4)</sup> Temperatura aria massima di oggi fino all'orario di aggiornamento (la temperatura massima della giornata normalmente si verifica nel primo pomeriggio in inverno e nel tardo pomeriggio in estate)";
    if (COLONNA == 'humidex') {
        sPostille +="<br><sup>(5)</sup> Indice Humidex è uno degli indici usati per stimare la temperatura percepita, all'orario di aggiornamento, in caso di disagio fisiologico da caldo-umido";
    }
    if (COLONNA == 'windchill') {
        sPostille +="<br><sup>(5)</sup> Il Windchill è un indice che descrive la differenza tra la temperatura effettivamente misurata e la percezione di freddo, tenendo conto dell'effetto di raffreddamento dovuto al vento";
    }
    sPostille += 
        "<br><sup>(6)</sup> Precipitazione cumulata di oggi fino all'orario di aggiornamento" +
        "<br><sup>(7)</sup> Raffica massima del vento di oggi fino all'orario di aggiornamento" +
        "<br>Alcune stazioni non rilevano tutti i parametri presentati nella tabella";

    if (METTI_NEVE) {
        sPostille += "<br><sup>(8)</sup> Altezza neve all'ora di aggiornamento"
    }

    document.getElementById('InfoColonne').innerHTML = sPostille;

    let orarioAggi = null;

    // ciclo 
    stzData.forEach( stazio => {       

            var row = body.insertRow(-1);

            row.insertCell(-1).innerHTML = stazio.nome_stazione;

            addCellValue(row, stazio.quota);
            addCellValue(row, stazio.provincia, 'center');

            const quando = new Date().ConvIstante( stazio.dataora_aggiornamento );
            addCellValue(row, quando.Formato('HH:mm'));

            // prendo l'orario più recente
            if ( orarioAggi == null) {
                orarioAggi = quando;
            }
            if (orarioAggi < quando) {
                orarioAggi = quando;
            }

            addCellValue(row, UnDecimale( stazio.ultima_temp_aria) );
            addCellValue(row, UnDecimale( stazio.temp_aria_min) );
            addCellValue(row, UnDecimale( stazio.temp_aria_max) );
            if (COLONNA == 'humidex') {
                addCellValue(row, UnDecimale( stazio.humidex) );
            }
            if (COLONNA == 'windchill') {
                addCellValue(row, UnDecimale( stazio.windchill) );
            }
            addCellValue(row, UnDecimale( stazio.precipitazione) );

            if (isNumeric(stazio.velo_vento_raffica)) {
                addCellValue(row, UnDecimale(  Math.round( stazio.velo_vento_raffica * 3.6 *10)/10 ) );
            } else {
                addCellValue(row, UnDecimale( stazio.velo_vento_raffica) );
            }

            if (METTI_NEVE) {
                addCellValue(row, stazio.altezza_neve);
            }

            let grafico = row.insertCell(-1);
            grafico.innerHTML = 'Grafico';
            grafico.style.textAlign = 'center';
            grafico.style.verticalAlign = 'middle';
            grafico.onclick = function () { vediGrafico( stazio.codseqst ); }
            grafico.onmouseover = function () { grafico.style.cursor = "pointer"; }
            grafico.onmouseout = function () { grafico.style.cursor = "default"; }

    });
    var divTab = document.createElement('div');
    divTab.setAttribute('id', 'tabElencoStazioni');
    divTab.setAttribute('class', 'bmodal-body');
    divTab.style.height = "900px";    
    divTab.style.overflowY = "scroll";    
    divTab.append(table);

    document.getElementById('tabellaStazioni').innerHTML = '';
    document.getElementById('tabellaStazioni').append(divTab);
    document.getElementById('tabellaStazioni').style.border = "";

    document.getElementById('orarioRifer').innerHTML = orarioAggi.Formato('HH:mm');
    document.getElementById('giornoRifer').innerHTML = orarioAggi.Formato('DD/MM/YYYY');

}

/**
 * 
 */
function vediGrafico( codseqst ) {

    const lnk = lnkGrafici + codseqst;

    document.location.href = lnk;

}

